# owner: platform
"""Short absence notices for parents, built from one student's marks."""

import typing

import rosterkit.models
import rosterkit.attendance


def ensure_own_marks(student: rosterkit.models.Student, marks: list) -> None:
    """Marks for anyone other than the student are an error."""
    for mark in marks:
        if mark.student_id != student.student_id:
            raise ValueError(f"{mark.student_id!r} is not {student.student_id!r}")


def checked_absences(student: rosterkit.models.Student, marks: list) -> list:
    """Absent days for one student. Having nothing to report is an error."""
    ensure_own_marks(student, marks)
    missed = rosterkit.attendance.days_missed(marks)
    if not missed:
        raise ValueError(f"no absences to report for {student.student_id!r}")
    return missed


def date_list(days: list) -> str:
    """ISO dates joined with commas, in the order given."""
    texts = []
    for day in days:
        texts.append(day.isoformat())
    return ", ".join(texts)


def absence_notice(
    student: rosterkit.models.Student, marks: typing.Iterable[rosterkit.models.Mark]
) -> str:
    """Short notice for a parent naming the student and each absent day."""
    missed = checked_absences(student, list(marks))
    noun = "day" if len(missed) == 1 else "days"
    return f"{student.display_name} missed {len(missed)} {noun}: {date_list(missed)}."

after.tests/test_notices.py:
# owner: platform
"""Tests for the parent absence notices."""

import unittest
import rosterkit.notices
import rosterkit.models
import datetime


def make_student(student_id: str) -> rosterkit.models.Student:
    return rosterkit.models.Student(student_id, "Smith", "Jane", "AB")


def make_mark(student_id: str, day: str, status: str) -> rosterkit.models.Mark:
    return rosterkit.models.Mark(student_id, datetime.date.fromisoformat(day), status)


class NoticeTests(unittest.TestCase):
    def setUp(self):
        self.student = make_student("ana")

    def test_lists_absent_days_oldest_first(self):
        marks = [
            make_mark("ana", "2026-09-05", "absent"),
            make_mark("ana", "2026-09-01", "absent"),
        ]
        notice = rosterkit.notices.absence_notice(self.student, marks)
        self.assertTrue(notice == "Smith, Jane missed 2 days: 2026-09-01, 2026-09-05.")

    def test_single_day_uses_singular(self):
        marks = [
            make_mark("ana", "2026-09-01", "absent"),
            make_mark("ana", "2026-09-02", "present"),
            make_mark("ana", "2026-09-03", "excused"),
        ]
        notice = rosterkit.notices.absence_notice(self.student, marks)
        self.assertTrue(notice == "Smith, Jane missed 1 day: 2026-09-01.")

    def test_other_students_marks_raise(self):
        marks = [
            make_mark("ana", "2026-09-01", "absent"),
            make_mark("ben", "2026-09-02", "absent"),
        ]
        with self.assertRaises(ValueError):
            rosterkit.notices.absence_notice(self.student, marks)

    def test_no_absences_raises(self):
        marks = [
            make_mark("ana", "2026-09-01", "present"),
            make_mark("ana", "2026-09-02", "excused"),
        ]
        with self.assertRaises(ValueError):
            rosterkit.notices.absence_notice(self.student, marks)
